import os, pty, sys, select, subprocess, time
def drive(argv, answers, cwd='/tmp/w/fmt', timeout=25):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd)
        try: os.execv(argv[0], argv)
        except Exception: os._exit(127)
    out=b''; ai=0; t0=time.time()
    while True:
        if time.time()-t0>timeout: break
        r,_,_=select.select([fd],[],[],0.4)
        if r:
            try: c=os.read(fd,65536)
            except OSError: break
            if not c: break
            out+=c
            if ai<len(answers) and (b':' in out[-200:] or b'?' in out[-200:]):
                time.sleep(0.15); os.write(fd, answers[ai].encode()); ai+=1
        else:
            if ai<len(answers):
                time.sleep(0.2); os.write(fd, answers[ai].encode()); ai+=1
    try: os.close(fd)
    except OSError: pass
    _,st=os.waitpid(pid,0)
    return out, (st>>8) if (st&0xff)==0 else -(st&0x7f)
if __name__=='__main__':
    import json
    argv=sys.argv[1:]
    ans=json.loads(os.environ.get('ANS','[]'))
    o,c=drive(argv,ans)
    sys.stdout.write(repr(o)+"\nEXIT=%d\n"%c)
